INSERT INTO dump_descriptions (base_key, description) VALUES ('deep_dive_carry', 'Sets enemy-count, damage, and large-enemy resistance scaling to the four-player values across standard Hazard 3–5 and Deep Dive Hazard 3.5–5.5; renames Hazard 5 to “Carry5”.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('deep_dive_carry_x2_enemies', 'Raises enemy-count scaling to about 2.8–3× across Hazard 5 and Deep Dive Hazard 4.5–5.5, while flattening enemy damage and large-enemy resistance to the four-player values.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
